def transform(grid):
    g = np.array(grid)
    bg = background(g)
    colmap = {8: 1, 2: 2, 4: 3, 3: 4}
    out = np.full_like(g, bg)
    emit(out.copy(), "Clear the input column: every coloured cell will be moved to a new column.")
    cells = [(y, x, int(g[y, x])) for y in range(g.shape[0]) for x in range(g.shape[1]) if g[y, x] != bg]
    for c in sorted(set(v for _, _, v in cells), key=lambda c: colmap.get(c, 0)):
        nx = colmap.get(c, 0)
        for y, x, v in cells:
            if v == c:
                out[y, min(nx, g.shape[1] - 1)] = c
        emit(out.copy(), f"Place every colour-{c} cell in its own row at column {nx} (legend: 8->1, 2->2, 4->3, 3->4).")
    emit(out.copy(), "Final grid: each cell shifted right by the column its colour dictates.")
    return out
